// Astrid's trust and quests count races completed after meeting the queen.
const royalQuests=[
{id:'first',name:'Ditt första kungliga race',message:'Visa mig ditt mod. Ta dig i mål i ett race – varje placering räknas!',goal:1,progress:()=>state.royalRaces,reward:15},
{id:'explore',name:'Hälsningar från hela riket',message:'Besök Näckrosdammen, Svampskogen och Månskensmyren. Mitt rike har så mycket att visa dig!',goal:3,progress:()=>state.visitedTracks.length,reward:30},
{id:'practice',name:'Små språng, stort mod',message:'Fullfölj fem race. Jag tror på dig, och varje försök gör dig starkare.',goal:5,progress:()=>state.royalRaces,reward:25},
{id:'victory',name:'En seger att fira',message:'Vinn ett race så får jag kröna dig. Ta den tid du behöver – jag hejar på dig!',goal:1,progress:()=>state.royalWins,reward:25}
];
function trustMeter(){const level=Math.floor(state.trust/100),next=(level+1)*100;return `<div class="trustMeter"><div><strong>✧ Astrids förtroende</strong><span>${state.trust} poäng</span></div><progress max="100" value="${state.trust%100}" aria-label="Astrids förtroende, nivå ${level+1}"></progress><small>Nivå ${level+1} · ${next-state.trust} till nästa nivå</small></div>`}
function recordRoyalRace(rank,track){if(state.village&&track===0)state.village.pondTrips++;const earned=rank===1?10:5;state.trust+=earned;state.royalRaces++;if(rank===1)state.royalWins++;if(!state.visitedTracks.includes(track))state.visitedTracks.push(track);return earned}
function claimRoyalQuest(id){const q=royalQuests.find(q=>q.id===id);if(!q||state.claimedQuests.includes(id)||q.progress()<q.goal)return false;state.claimedQuests.push(id);state.trust+=q.reward;save();return true}
function renderAstrid(){$('#content').innerHTML=`<section class="queenHero"><img src="assets/astrid-portrait.png" alt="Drottning Astrid med gyllene krona, gröna kläder och skimrande vingar"><div><div class="eyebrow">ÄLVVÄRLDENS DROTTNING</div><h2>Välkommen till mitt rike!</h2><p>Jag är Astrid, drottning över hela älvvärlden. Här är varje modigt språng värt att fira. Jag ger startsignalen och kröner vinnaren i varje race.</p><blockquote>”Du behöver inte vinna varje gång för att vinna mitt förtroende. Fortsätt försöka – jag tror på dig!”</blockquote></div></section>${trustMeter()}<button class="primary" id="royalAdventure">Astrids äventyrsuppdrag →</button><p class="royalExplain">Varje fullföljt race ger 5 förtroendepoäng, eller 10 om du vinner. Mina uppdrag ger extra förtroende. Mätaren fortsätter växa, nivå för nivå.</p><div class="sectionHead"><h2>Uppdrag från Astrid</h2><span class="pill">${royalQuests.filter(q=>q.progress()>=q.goal||state.claimedQuests.includes(q.id)).length} av ${royalQuests.length} klara</span></div><div class="royalQuests">${royalQuests.map(q=>{const done=state.claimedQuests.includes(q.id),n=Math.min(q.goal,q.progress()),ready=n>=q.goal;return `<article class="quest"><div class="eyebrow">${done?'✓ BELÖNING HÄMTAD':ready?'✓ KLART – HÄMTA BELÖNING':n>0?'PÅGÅR':'INTE PÅBÖRJAT'}</div><h3>${q.name}</h3><p>”${q.message}”</p><div class="questProgress"><span>${n} / ${q.goal}</span><strong>✧ +${q.reward} förtroende</strong></div><progress value="${n}" max="${q.goal}" aria-label="${q.name}"></progress><button class="${ready&&!done?'primary':'outline'}" ${ready||done?`data-quest="${q.id}"`:`data-quest-race="${q.id}"`} ${done?'disabled':''}>${done?'✓ Astrid har tackat dig':ready?'Ta emot Astrids tack':n>0?'Fortsätt tävla →':'Till loppen →'}</button></article>`}).join('')}</div><p class="royalExplain">Uppdragen räknar race från den här uppdateringen. Du behöver inte aktivera uppdragen. Dina framsteg räknas automatiskt när du går i mål. Varje uppdragsbelöning kan hämtas en gång.</p>`;$('#royalAdventure').onclick=()=>{tab='adventure';render()};document.querySelectorAll('[data-quest-race]').forEach(b=>b.onclick=()=>{if(b.dataset.questRace==='explore'){const missing=[0,1,2].find(i=>!state.visitedTracks.includes(i));if(missing!==undefined)chosen=missing}tab='race';render()});document.querySelectorAll('[data-quest]').forEach(b=>b.onclick=()=>{if(claimRoyalQuest(b.dataset.quest)){sidebar();renderAstrid();toast('Astrid: Tack, min vän! Mitt förtroende för dig har vuxit.')}})}
function astridStart(){if(running||!state.hatched)return;running=true;$('#content').innerHTML=`<section class="queenHero startCeremony"><img src="assets/astrid-start.png" alt="Astrid lyfter sin gyllene stav för att starta racet"><div><div class="eyebrow">ASTRID GER STARTSIGNALEN</div><h2>${activeRun?.kind==='cup'?'Kungliga mästerskapet · ':''}${races[chosen].name}</h2><blockquote>”Välkomna, mina modiga vänner! Ta hand om era grodor och njut av varje språng. Jag hejar på er alla!”</blockquote><p id="royalCountdown" role="status">Astrid väntar tills du är redo.</p><button class="primary" id="royalReady">Jag är redo!</button><button class="outline" id="royalBack">Tillbaka till loppen</button></div></section>`;$('#royalBack').onclick=()=>{running=false;activeRun=null;render()};$('#royalReady').onclick=()=>{$('#royalReady').disabled=true;$('#royalBack').disabled=true;let n=3;$('#royalCountdown').textContent='Astrid höjer staven… '+n;const timer=setInterval(()=>{n--;if(n>0){$('#royalCountdown').textContent='Klara… '+n}else{clearInterval(timer);startRace();$('#raceTitle').textContent='Astrid: Låt racet börja!'}},1000)}}
function coronation(rank,reward,earned,winner){const winnerName=winner===0?'ditt team':['','Klöver','Mossa','Pärla'][winner];return `<section class="queenHero coronation"><img src="assets/astrid-crown.png" alt="Drottning Astrid vid den kungliga prisutdelningen"><div><div class="eyebrow">ASTRIDS KRÖNING</div><h2>♛ ${rank===1?'Du är racets vinnare!':winnerName+' kröns till vinnare'}</h2><p class="winnerCrown">♛</p><blockquote>${rank===1?'”Med glädje kröner jag dig till vinnare! Vilka fantastiska språng. Hela älvvärlden firar med dig!”':'”Grattis till vinnaren! Och tack för ditt mod, min vän. Var stolt över att du tog dig i mål – ditt nästa äventyr väntar.”'}</blockquote><p>Din placering: ${rank} av 4 · +${reward} daggdroppar<br><strong>✧ +${earned} förtroende hos Astrid</strong></p></div></section>${trustMeter()}${royalQuests.some(q=>!state.claimedQuests.includes(q.id)&&q.progress()>=q.goal)?'<p class="questNotice">✧ Du har uppdrag klara! Besök Drottning Astrid för att ta emot hennes tack.</p>':''}<button class="primary" id="again">Tillbaka till loppen →</button>`}
